const G=window.STAR_EMBER_GAME,CLOUD=window.StarEmberCloud;
const SAVE_KEY='starEmber.save.v20';
class SaveAdapter{
  load(){for(const key of [SAVE_KEY,'starEmber.save.v19','starEmber.save.v18','starEmber.save.v17','starEmber.save.v16','starEmber.save.v15','starEmber.save.v14','starEmber.save.v13','starEmber.save.v12','starEmber.save.v11','starEmber.save.v10','starEmber.save.v9','starEmber.save.v8','starEmber.save.v7','starEmber.save.v6','starEmber.save.v5','starEmber.save.v4','starEmber.save.v3','starEmber.save.v2','starEmber.save.v1']){try{const raw=localStorage.getItem(key);if(raw)return G.migrate(JSON.parse(raw),'local-player')}catch{}}return null}
  save(s){localStorage.setItem(SAVE_KEY,JSON.stringify(s))}
  reset(){['starEmber.save.v20','starEmber.save.v19','starEmber.save.v18','starEmber.save.v17','starEmber.save.v16','starEmber.save.v15','starEmber.save.v14','starEmber.save.v13','starEmber.save.v12','starEmber.save.v11','starEmber.save.v10','starEmber.save.v9','starEmber.save.v8','starEmber.save.v7','starEmber.save.v6','starEmber.save.v5','starEmber.save.v4','starEmber.save.v3','starEmber.save.v2','starEmber.save.v1'].forEach(k=>localStorage.removeItem(k))}
}
const saves=new SaveAdapter();
let state=saves.load()||G.newPlayer('guest-'+Math.random().toString(36).slice(2,10));
let selectedBattleTargetId=null,battlePaused=false;let tab='home',lastGacha=[],gachaPool='standard',battleLog=[],lastBattle=null,battleFrame=0,battleTimer=null,cloudMode=false,busy=false,toastTimer,currentLink=null,eventLeaderboard=[],selectedHeroId=state.formation[0]||Object.keys(state.heroes)[0],settingsOpen=false,revealOpen=false,revealIndex=0,booting=true,bossIntroOpen=false,storyOpen=false,storyIndex=0,resultOpen=false,archiveOpen=false,archiveHeroId=null,liveSession=state.activeBattleSession||null;
const UI_KEY='starEmber.ui.v20';
function loadUi(){const base={tutorialDone:false,tutorialStep:0,firstContractDone:false,sound:true,music:true,voice:true,battleSpeed:1,skillMode:'auto',manualSkills:[],autoStrategy:'balanced',presetSlot:'1',fxQuality:'high'};for(const key of [UI_KEY,'starEmber.ui.v19','starEmber.ui.v18','starEmber.ui.v17','starEmber.ui.v16','starEmber.ui.v15','starEmber.ui.v14','starEmber.ui.v13','starEmber.ui.v12','starEmber.ui.v11','starEmber.ui.v10']){try{const raw=localStorage.getItem(key);if(raw)return Object.assign(base,JSON.parse(raw))}catch{}}return base}
let ui=loadUi();function saveUi(){localStorage.setItem(UI_KEY,JSON.stringify(ui))}
let audioCtx=null;function sfx(kind='tap'){if(!ui.sound)return;try{audioCtx||=new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);const f={tap:420,gacha:620,rare:920,skill:760,win:1040}[kind]||480;o.frequency.value=f;g.gain.setValueAtTime(.045,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.12);o.start();o.stop(audioCtx.currentTime+.13)}catch{}}
G.ensureDaily(state);

function playVoice(heroId,type='acquire'){if(!ui.voice)return;const cfg=G.HERO_VOICES?.[heroId],line=cfg?.[type];if(!line)return;try{if('speechSynthesis' in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(line);u.lang='zh-CN';u.rate=.95;u.pitch=1.02;window.speechSynthesis.speak(u)}}catch{}toast(`语音预览 · ${line}`)}

const skillText={burst:'高倍率单体爆发',aoe:'敌方全体伤害',cleanseSupport:'全队治疗、强化并净化异常',heal:'治疗生命最低队友',stun:'伤害并概率眩晕',tauntShield:'全队护盾并嘲讽敌方',multi:'随机三连击',execute:'优先攻击残血并获得斩杀加成',selfShield:'获得高额个人护盾',aoeLite:'小范围全体伤害',executeLite:'优先追击残血',silence:'伤害、减速并沉默目标',buff:'强化全队攻击',burstLite:'单体强击',healAll:'恢复全队生命'};
const slotName={weapon:'武器',armor:'护甲',charm:'饰物'};
function persist(){state.lastLogin=new Date().toISOString();if(!cloudMode)saves.save(state)}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=text;document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2200)}
function errorText(code){return({NOT_ENOUGH_TICKETS:'契灵印不足',NOT_ENOUGH_COIN:'烬币不足',NOT_ENOUGH_FRAGMENTS:'角色碎片不足',STAR_CAP:'已达到5星',LEVEL_CAP:'已达到50级',INVALID_FORMATION:'阵容配置无效',CLOUD_NOT_CONFIGURED:'尚未填写 CloudBase 配置',UNAUTHENTICATED:'云端身份未登录',CONFLICT_RETRY:'数据正在被另一设备更新，请重试',TASK_NOT_FOUND:'任务不存在',TASK_ALREADY_CLAIMED:'任务奖励已领取',TASK_NOT_READY:'任务尚未完成',DAILY_ALL_ALREADY_CLAIMED:'今日全勤奖励已领取',DAILY_ALL_NOT_READY:'请先领取全部每日任务奖励',INVALID_LINK_CODE:'迁移码无效',LINK_CODE_EXPIRED:'迁移码已过期，请重新生成',IDENTITY_ALREADY_LINKED:'当前身份已经绑定其他玩家数据',LINK_WOULD_REPLACE_PROGRESS:'当前设备已有游戏进度，为避免覆盖已阻止绑定',ITEM_NOT_FOUND:'装备或遗物不存在',ITEM_NOT_OWNED:'尚未获得该装备或遗物',ITEM_IN_USE:'这件装备已被其他角色占用',INVALID_SLOT:'装备槽位无效',INVALID_LOADOUT_ACTION:'装备操作无效',NOT_ENOUGH_STAR_IRON:'星铁不足',ENHANCE_CAP:'装备已强化至+10',DUNGEON_NOT_FOUND:'资源副本不存在',DUNGEON_ATTEMPTS_EXHAUSTED:'今日挑战次数已用完',POWER_TOO_LOW:'当前阵容战力不足',ACHIEVEMENT_NOT_FOUND:'成就不存在',ACHIEVEMENT_ALREADY_CLAIMED:'成就奖励已领取',ACHIEVEMENT_NOT_READY:'尚未达成该成就',WEEKLY_TASK_NOT_FOUND:'周任务不存在',WEEKLY_TASK_ALREADY_CLAIMED:'周任务奖励已领取',WEEKLY_TASK_NOT_READY:'周任务尚未完成',WEEKLY_ALL_ALREADY_CLAIMED:'本周全勤奖励已领取',WEEKLY_ALL_NOT_READY:'请先领取全部周任务奖励',SHOP_ITEM_NOT_FOUND:'商店商品不存在',SHOP_LIMIT_REACHED:'该商品今日已达购买上限',NOT_ENOUGH_STAR_CRYSTAL:'星髓不足',NO_SPARE_EQUIPMENT:'没有可分解的闲置装备',FORGE_RECIPE_NOT_FOUND:'锻造配方不存在',NOT_ENOUGH_FORGE_DUST:'锻造尘不足',NOT_ENOUGH_BOND_GIFT:'星语花不足',EVENT_STAGE_NOT_FOUND:'活动关卡不存在',EVENT_SHOP_ITEM_NOT_FOUND:'活动商品不存在',EVENT_SHOP_LIMIT_REACHED:'该活动商品已兑换完',NOT_ENOUGH_MOON_SEAL:'月蚀印不足',EVENT_ATTEMPTS_EXHAUSTED:'今日活动挑战次数已用完',SIGNATURE_NOT_FOUND:'专属武器不存在',SIGNATURE_NOT_OWNED:'尚未获得该专属武器',SIGNATURE_HERO_MISMATCH:'该契印武装不属于这名角色',AWAKEN_CAP:'角色已完成三阶觉醒',AWAKEN_LEVEL_REQUIRED:'角色等级未达到觉醒要求',AWAKEN_STAR_REQUIRED:'角色需要达到5星才能觉醒',NOT_ENOUGH_AWAKENING_CORE:'觉醒核心不足',MAIL_NOT_FOUND:'邮件不存在',MAIL_ALREADY_CLAIMED:'邮件奖励已领取',NO_MAIL_REWARD:'没有可领取的邮件',EVENT_BOSS_ATTEMPTS_EXHAUSTED:'今日活动Boss挑战次数已用完',LOGIN_REWARD_ALREADY_CLAIMED:'今日登录奖励已经领取',ACTIVE_BATTLE_SESSION:'已有未结束的手动战斗，请继续或取消',BATTLE_SESSION_NOT_FOUND:'没有可恢复的战斗会话',BATTLE_SESSION_NOT_WAITING:'当前战斗未等待技能指令',BATTLE_SESSION_ACTOR_MISMATCH:'技能指令角色不匹配',INVALID_BATTLE_COMMAND:'无效的战斗指令',BATTLE_SESSION_ALREADY_COMPLETE:'战斗已经结束',TALENT_NOT_FOUND:'天赋节点不存在',TALENT_ALREADY_UNLOCKED:'该天赋已点亮',TALENT_REQUIREMENT:'请先解锁前置天赋',NOT_ENOUGH_TALENT_POINTS:'星痕点不足',INVALID_PRESET_SLOT:'阵容预设槽位无效',PRESET_NOT_FOUND:'该阵容预设尚未保存',PRESET_EMPTY:'阵容预设没有可用角色',STAGE_NOT_CLEARED:'该关卡尚未通关，无法扫荡',SWEEP_LIMIT:'今日扫荡次数不足',NIGHT_EVENT_STAGE_NOT_FOUND:'夜航活动关卡不存在',NIGHT_EVENT_ATTEMPTS_EXHAUSTED:'今日夜航挑战次数已用完',NIGHT_EVENT_SHOP_ITEM_NOT_FOUND:'夜航商品不存在',NIGHT_EVENT_SHOP_LIMIT:'该夜航商品已兑换完',NOT_ENOUGH_VOYAGE_BADGE:'航星徽不足'}[code]||code||'操作失败')}
async function action(fn){if(busy)return;busy=true;render();try{await fn()}catch(e){console.error(e);toast(errorText(e.code||e.message))}finally{busy=false;render()}}
function rarityRank(r){return r==='SSR'?3:r==='SR'?2:1}
function ownedList(){return Object.entries(state.heroes).map(([id,p])=>({...G.byId(id),...p})).filter(x=>x.id).sort((a,b)=>rarityRank(b.rarity)-rarityRank(a.rarity)||b.star-a.star||b.level-a.level)}
function stars(n){return '★'.repeat(n)+'☆'.repeat(5-n)}
function rewardText(r){return[r.coin?`烬币 ${r.coin}`:'',r.tickets?`契灵印 ${r.tickets}`:'',r.starCrystal?`星髓 ${r.starCrystal}`:'',r.starIron?`星铁 ${r.starIron}`:'',r.forgeDust?`锻造尘 ${r.forgeDust}`:'',r.bondGift?`星语花 ${r.bondGift}`:'',r.moonSeal?`月蚀印 ${r.moonSeal}`:'',r.awakeningCore?`觉醒核心 ${r.awakeningCore}`:'',r.talentPoints?`星痕点 ${r.talentPoints}`:'',r.voyageBadge?`航星徽 ${r.voyageBadge}`:'',r.signatureWeapon?`${G.signatureById(r.signatureWeapon)?.name||'专属武器'} ×1`:'',r.fragments?`角色碎片 ${r.fragments}`:''].filter(Boolean).join(' · ')}
function statText(stats){return Object.entries(stats||{}).map(([k,v])=>`${({hp:'生命',atk:'攻击',def:'防御',spd:'速度'})[k]} +${v}`).join(' · ')}
function currentBoss(){return G.bossByStage(state.stage)}
function currentChapter(){return G.chapterByStage(state.stage)}
function classBadge(hero){const id=G.combatClassForHero(hero),c=G.combatClassInfo(id);return `<span class="v18-class ${id}">${c.icon} ${c.name}</span>`}
function skillIcon(heroId,cls='v19-skill-icon v20-skill-icon'){const src=window.StarEmberAssets?.skill(heroId)||`assets/ui/skills/${heroId}.svg`;return `<img class="${cls}" src="${src}" alt=""/>`}
function statusIcon(id,label=''){const src=window.StarEmberAssets?.status(id)||'';return src?`<span class="v19-status-chip"><img src="${src}" alt=""/>${label}</span>`:`<span class="v19-status-chip">${label}</span>`}
function bossEmblem(stage){const src=window.StarEmberAssets?.boss(stage)||`assets/ui/bosses/stage-${stage}.svg`;return `<img class="v19-boss-emblem" src="${src}" alt="Boss"/>`}
async function talentUnlock(heroId,nodeId){await action(async()=>{if(cloudMode){const d=await CLOUD.unlockTalent(heroId,nodeId);state=G.migrate(d.state)}else{G.unlockTalent(state,heroId,nodeId);persist()}toast('天赋已点亮')})}
async function presetAction(kind,slot){await action(async()=>{if(cloudMode){const d=await CLOUD.formationPreset(kind,slot,`阵容 ${slot}`);state=G.migrate(d.state)}else{kind==='save'?G.saveFormationPreset(state,slot,`阵容 ${slot}`):G.loadFormationPreset(state,slot);persist()}toast(kind==='save'?`阵容 ${slot} 已保存`:`已载入阵容 ${slot}`)})}
async function sweepRun(count=1){const stage=Math.max(1,state.stage-1);await action(async()=>{let r;if(cloudMode){const d=await CLOUD.sweep(stage,count);state=G.migrate(d.state);r=d.sweep}else{r=G.sweepStage(state,stage,count);persist()}toast(`扫荡 Stage ${stage} ×${count}：${rewardText(r.reward)}`);tab='explore'})}
async function nightRun(id){await action(async()=>{let r;if(cloudMode){const d=await CLOUD.nightVoyage('battle',id);state=G.migrate(d.state);r=d.result}else{r=G.nightEventBattle(state,id);persist()}toast(`夜航完成：${r.name}`);tab='event'})}
async function nightBuy(id){await action(async()=>{let r;if(cloudMode){const d=await CLOUD.nightVoyage('buy',id);state=G.migrate(d.state);r=d.result}else{r=G.nightEventShopBuy(state,id);persist()}toast(`兑换：${rewardText(r.reward)}`);tab='event'})}


async function gacha(count){await action(async()=>{if(state.tickets<count)throw Object.assign(new Error('NOT_ENOUGH_TICKETS'),{code:'NOT_ENOUGH_TICKETS'});const starter=count===10&&!state.newbieGacha?.claimed;if(starter){ui.firstContractDone=true;saveUi()}if(cloudMode){const d=starter?await CLOUD.newbieGacha():await CLOUD.gacha(count);state=G.migrate(d.state);lastGacha=d.results}else{lastGacha=starter?G.pullStarterTen(state):G.pull(state,count);persist()}tab='gacha';revealOpen=true;revealIndex=0;if(lastGacha[0]?.hero)playVoice(lastGacha[0].hero.id,'acquire');sfx(lastGacha.some(x=>x.hero.rarity==='SSR')?'rare':'gacha')})}
async function limitedGacha(count){await action(async()=>{if(state.tickets<count)throw Object.assign(new Error('NOT_ENOUGH_TICKETS'),{code:'NOT_ENOUGH_TICKETS'});if(cloudMode){const d=await CLOUD.limitedGacha(count);state=G.migrate(d.state);lastGacha=d.results}else{lastGacha=G.pullLimited(state,count);persist()}gachaPool='limited';tab='gacha';revealOpen=true;revealIndex=0;sfx(lastGacha.some(x=>x.hero.rarity==='SSR')?'rare':'gacha')})}
async function shopBuy(id){await action(async()=>{let d;if(cloudMode){d=await CLOUD.shopBuy(id);state=G.migrate(d.state)}else{d={purchase:G.shopBuy(state,id)};persist()}toast(`兑换成功：${rewardText(d.purchase.reward)}`);tab='shop'})}
async function claimWeekly(taskId,claimAll=false){await action(async()=>{if(cloudMode){const d=await CLOUD.claimWeekly(taskId,claimAll);state=G.migrate(d.state)}else{claimAll?G.claimWeeklyAll(state):G.claimWeeklyTask(state,taskId);persist()}toast(claimAll?'本周全勤奖励已领取':'周任务奖励已领取')})}
async function upgrade(id,type){await action(async()=>{const h=G.byId(id);if(cloudMode){const d=await CLOUD.upgrade(id,type);state=G.migrate(d.state)}else{type==='star'?G.starUp(state,id):G.levelUp(state,id);persist()}toast(`${h.name}${type==='level'?'升级成功':'升星成功'}`)})}
async function toggleFormation(id){const next=state.formation.includes(id)?state.formation.filter(x=>x!==id):[...state.formation,id];if(next.length<1){toast('阵容至少保留1名角色');return}if(next.length>5){toast('阵容最多5名角色');return}await action(async()=>{if(cloudMode){const d=await CLOUD.formation(next,state.formationRows||{});state=G.migrate(d.state)}else{G.setFormation(state,next,state.formationRows||{});persist()}selectedHeroId=state.formation[0]||selectedHeroId})}
function adoptLiveSession(session){liveSession=session||null;if(!liveSession)return;if(liveSession.pending?.targets?.length&&!liveSession.pending.targets.some(x=>x.id===selectedBattleTargetId))selectedBattleTargetId=liveSession.pending.targets[0].id;battleLog=liveSession.log||[];battleFrame=Math.max(0,(liveSession.timeline?.length||1)-1);if(liveSession.status==='complete'&&liveSession.result){lastBattle=liveSession.result;resultOpen=true;sfx(lastBattle.win?'win':'skill');if(lastBattle.drops?.length)toast(`获得 ${lastBattle.drops.map(x=>x.item.name).join('、')}`)}}
async function startLiveBattle(){await action(async()=>{if(!state.formation.length)throw Object.assign(new Error('INVALID_FORMATION'),{code:'INVALID_FORMATION'});let session;if(cloudMode){const d=await CLOUD.battleSessionStart({skillMode:'manual',autoStrategy:ui.autoStrategy});state=G.migrate(d.state);session=d.session}else{session=G.startBattleSession(state,{skillMode:'manual',autoStrategy:ui.autoStrategy});persist()}adoptLiveSession(session);tab='explore'})}
async function commandLiveBattle(command){await action(async()=>{if(!liveSession?.pending)throw Object.assign(new Error('BATTLE_SESSION_NOT_WAITING'),{code:'BATTLE_SESSION_NOT_WAITING'});let session;if(cloudMode){const d=await CLOUD.battleSessionCommand(liveSession.id,liveSession.pending.heroId,command,selectedBattleTargetId);state=G.migrate(d.state);session=d.session}else{session=G.battleSessionCommand(state,liveSession.id,liveSession.pending.heroId,command,undefined,selectedBattleTargetId);persist()}adoptLiveSession(session)})}
async function cancelLiveBattle(){await action(async()=>{if(!liveSession)return;if(cloudMode){const d=await CLOUD.battleSessionCancel(liveSession.id);state=G.migrate(d.state)}else{G.cancelBattleSession(state,liveSession.id);persist()}liveSession=null;battleLog=[];toast('已撤离当前战斗')})}
async function battle(){if(ui.skillMode==='manual')return startLiveBattle();await action(async()=>{if(!state.formation.length)throw Object.assign(new Error('INVALID_FORMATION'),{code:'INVALID_FORMATION'});let d;if(cloudMode){d=await CLOUD.battle({skillMode:'auto',autoStrategy:ui.autoStrategy});state=G.migrate(d.state);battleLog=d.battle.log}else{d={battle:G.battle(state,{skillMode:'auto',autoStrategy:ui.autoStrategy})};battleLog=d.battle.log;persist()}lastBattle=d.battle;liveSession=null;battleFrame=0;resultOpen=false;sfx(d.battle.win?'win':'skill');if(d.battle.drops?.length)toast(`获得 ${d.battle.drops.map(x=>x.item.name).join('、')}`);tab='explore'})}
async function claimDaily(taskId,claimAll=false){await action(async()=>{if(cloudMode){const d=await CLOUD.claimDaily(taskId,claimAll);state=G.migrate(d.state)}else{claimAll?G.claimDailyAll(state):G.claimDailyTask(state,taskId);persist()}toast(claimAll?'全勤奖励已领取':'任务奖励已领取')})}
async function claimLoginReward(){await action(async()=>{let d;if(cloudMode){d=await CLOUD.claimLoginReward();state=G.migrate(d.state)}else{d={claim:G.claimLoginReward(state)};persist()}toast(`登录第${d.claim.day}日：${rewardText(d.claim.reward)}`);sfx(d.claim.day===7?'rare':'gacha')})}
async function connectCloud(){await action(async()=>{if(!CLOUD.configured())throw Object.assign(new Error('CLOUD_NOT_CONFIGURED'),{code:'CLOUD_NOT_CONFIGURED'});const d=await CLOUD.connect();state=G.migrate(d.state);cloudMode=true;liveSession=state.activeBattleSession||null;selectedHeroId=state.formation[0]||Object.keys(state.heroes)[0];lastGacha=[];battleLog=liveSession?.log||[];toast(liveSession?.status==='waiting'?'已连接云端，并恢复未完成战斗':'已连接云端账号')})}
async function syncCloud(){await action(async()=>{if(!cloudMode)return connectCloud();const d=await CLOUD.load();state=G.migrate(d.state);liveSession=state.activeBattleSession||null;battleLog=liveSession?.log||battleLog;toast(liveSession?.status==='waiting'?'云端进度已刷新 · 手动战斗可继续':'云端进度已刷新')})}
async function createLinkCode(){await action(async()=>{if(!cloudMode)throw Object.assign(new Error('UNAUTHENTICATED'),{code:'UNAUTHENTICATED'});currentLink=await CLOUD.createLinkCode();toast('迁移码已生成，有效期10分钟')})}
async function redeemLinkCode(){const code=(document.getElementById('linkCodeInput')?.value||'').trim();if(!code){toast('请输入6位迁移码');return}await action(async()=>{if(!cloudMode)await connectCloud();const d=await CLOUD.redeemLinkCode(code);state=G.migrate(d.state);currentLink=null;toast('账号绑定成功，已切换到同一份云存档')})}
async function setLoadout(type,data){await action(async()=>{if(cloudMode){const d=await CLOUD.loadout({type,...data});state=G.migrate(d.state)}else{if(type==='gear')G.equipGear(state,data.heroId,data.itemId);else if(type==='unequip')G.unequipGear(state,data.heroId,data.slot);else G.equipRelic(state,data.itemId||null);persist()}toast(type==='relic'?'队伍遗物已更新':'装备已更新')})}

async function enhanceGear(itemId){await action(async()=>{const item=G.equipmentById(itemId);if(cloudMode){const d=await CLOUD.enhanceEquipment(itemId);state=G.migrate(d.state)}else{G.enhanceEquipment(state,itemId);persist()}toast(`${item.name} 强化成功`)})}
async function resourceDungeon(id){await action(async()=>{let d;if(cloudMode){d=await CLOUD.resourceDungeon(id);state=G.migrate(d.state)}else{d={run:G.resourceDungeon(state,id)};persist()}toast(`资源副本完成：${rewardText(d.run.reward)}`);tab='explore'})}
async function claimAchievement(id){await action(async()=>{if(cloudMode){const d=await CLOUD.claimAchievement(id);state=G.migrate(d.state)}else{G.claimAchievement(state,id);persist()}toast('成就奖励已领取')})}
async function dismantleGear(itemId){await action(async()=>{const item=G.equipmentById(itemId);let d;if(cloudMode){d=await CLOUD.dismantleEquipment(itemId,1);state=G.migrate(d.state)}else{d={dismantle:G.dismantleEquipment(state,itemId,1)};persist()}toast(`${item.name} 已分解 · +${d.dismantle.forgeDust}锻造尘`)})}
async function forgeGear(recipeId){await action(async()=>{let d;if(cloudMode){d=await CLOUD.forgeEquipment(recipeId);state=G.migrate(d.state)}else{d={forge:G.forgeEquipment(state,recipeId)};persist()}toast(`锻造完成：${d.forge.item.name}`);tab='inventory'})}
async function runEvent(id){await action(async()=>{let d;if(cloudMode){d=await CLOUD.eventBattle(id);state=G.migrate(d.state)}else{d={run:G.eventBattle(state,id)};persist()}toast(`${d.run.name} 通关 · ${rewardText(d.run.reward)}`);tab='event'})}
async function eventBuy(id){await action(async()=>{let d;if(cloudMode){d=await CLOUD.eventShopBuy(id);state=G.migrate(d.state)}else{d={purchase:G.eventShopBuy(state,id)};persist()}toast('活动商店兑换成功');tab='event'})}
async function giftBond(heroId){await action(async()=>{const h=G.byId(heroId);let d;if(cloudMode){d=await CLOUD.bondGift(heroId,1);state=G.migrate(d.state)}else{d={bond:G.giftHero(state,heroId,1)};persist()}toast(`${h.name} 好感提升至 Lv.${d.bond.info.level}`)})}

async function setSignature(heroId,signatureId){await action(async()=>{const sig=G.signatureById(signatureId);if(cloudMode){const d=await CLOUD.equipSignature(heroId,signatureId);state=G.migrate(d.state)}else{G.equipSignature(state,heroId,signatureId);persist()}toast(`已装备契印武装：${sig.name}`)})}
async function awaken(heroId){await action(async()=>{const h=G.byId(heroId);if(cloudMode){const d=await CLOUD.awakenHero(heroId);state=G.migrate(d.state)}else{G.awakenHero(state,heroId);persist()}toast(`${h.name} 觉醒成功`)})}
async function mailClaim(id,all=false){await action(async()=>{if(cloudMode){const d=await CLOUD.claimMail(id,all);state=G.migrate(d.state)}else{all?G.claimAllMail(state):G.claimMail(state,id);persist()}toast(all?'邮件奖励已全部领取':'邮件奖励已领取')})}
async function runEventBoss(){await action(async()=>{let d;if(cloudMode){d=await CLOUD.eventBoss();state=G.migrate(d.state);eventLeaderboard=d.leaderboard||[]}else{d={run:G.eventBossBattle(state)};eventLeaderboard=G.localEventLeaderboard(state);persist()}toast(`对月蚀兽造成 ${d.run.damage.toLocaleString()} 伤害`);tab='event'})}
async function refreshLeaderboard(){if(!cloudMode){eventLeaderboard=G.localEventLeaderboard(state);render();return}await action(async()=>{const d=await CLOUD.getLeaderboard();eventLeaderboard=d.leaderboard||[]})}

function renderTop(){const meta=CLOUD.meta?.()||{};return `<div class="topbar"><div class="brand"><div><div class="logo-mark">✦</div><div><h1>星烬契约</h1><span class="mode ${cloudMode?'online':'local'}">${cloudMode?(meta.identityKind==='wechat'?'微信云端':'云端账号'):'本地试玩'}</span></div></div><div class="resource"><span class="pill coin">烬币 ${state.coin}</span><span class="pill crystal">星髓 ${state.starCrystal}</span><span class="pill ticket">契灵印 ${state.tickets}</span><span class="pill iron">星铁 ${state.inventory.starIron||0}</span><span class="pill dust">锻造尘 ${state.inventory.forgeDust||0}</span><span class="pill core">觉醒核 ${state.inventory.awakeningCore||0}</span><span class="pill mail">邮件 ${G.unreadMailCount(state)}</span><button class="v10-settings-btn" data-action="settings" title="设置">⚙</button></div></div></div>`}

function portrait(h,size='card'){const v=G.HERO_VISUALS[h.id]||{},src=window.StarEmberAssets?.heroPortrait(h.id,size==='profile'||size==='archive'||size==='reveal')||`assets/characters/${h.id}.jpg`,skill=window.StarEmberAssets?.skill(h.id)||'';return `<div class="hero-portrait ${size} portrait-${h.id} art-loaded" title="${v.title||h.name}"><img src="${src}" alt="${h.name}" onerror="this.style.display='none';this.parentElement.classList.remove('art-loaded')"/><div class="portrait-aura"></div><div class="portrait-halo"></div><div class="portrait-body"></div><div class="portrait-face"></div><div class="portrait-hair"></div><div class="portrait-weapon"></div><img class="v19-portrait-skill" src="${skill}" alt=""/><div class="portrait-sigil">✦</div></div>`}
function achievementPanel(){const rows=G.ACHIEVEMENTS.map(a=>{const p=G.achievementProgress(state,a),done=p>=a.goal,claimed=!!state.achievements?.claimed?.[a.id];return `<div class="achievement ${claimed?'claimed':done?'ready':''}"><div class="achievement-icon">${claimed?'✓':done?'✦':'◇'}</div><div class="achievement-main"><strong>${a.name}</strong><span>${a.desc}</span><div class="task-progress"><i style="width:${Math.min(100,p/a.goal*100)}%"></i></div><small>${Math.min(p,a.goal)}/${a.goal} · ${rewardText(a.reward)}</small></div><button class="btn ${done&&!claimed?'primary':'ghost'} compact" data-action="claimAchievement" data-id="${a.id}" ${!done||claimed?'disabled':''}>${claimed?'已领取':done?'领取':'未达成'}</button></div>`}).join('');return `<div class="panel"><div class="section-title"><h3>星烬成就</h3><span class="small muted">长期目标</span></div>${rows}</div>`}
function dailyPanel(){G.ensureDaily(state);const items=G.DAILY_TASKS.map(t=>{const p=state.daily.progress[t.id]||0,done=p>=t.goal,claimed=!!state.daily.claimed[t.id];return `<div class="task"><div class="task-main"><strong>${t.name}</strong><span>${t.desc}</span><div class="task-progress"><i style="width:${Math.min(100,p/t.goal*100)}%"></i></div><small>${p}/${t.goal} · ${rewardText(t.reward)}</small></div><button class="btn ${claimed?'ghost':done?'primary':'secondary'} compact" data-action="claimDaily" data-id="${t.id}" ${claimed||!done?'disabled':''}>${claimed?'已领取':done?'领取':'进行中'}</button></div>`}).join('');const allReady=G.DAILY_TASKS.every(t=>state.daily.claimed[t.id]);return `<div class="panel"><div class="section-title"><h3>今日星约</h3><span class="small muted">${state.daily.day}</span></div>${items}<div class="all-reward"><div><strong>全勤契约</strong><div class="small muted">全部任务领取后可得 ${rewardText(G.DAILY_ALL_REWARD)}</div></div><button class="btn primary compact" data-action="claimAll" ${!allReady||state.daily.allClaimed?'disabled':''}>${state.daily.allClaimed?'已领取':'领取'}</button></div></div>`}
function weeklyPanel(){G.ensureWeekly(state);const items=G.WEEKLY_TASKS.map(w=>{const p=state.weekly.progress[w.id]||0,done=p>=w.goal,claimed=!!state.weekly.claimed[w.id];return `<div class="task weekly-task"><div class="task-main"><strong>${w.name}</strong><span>${w.desc}</span><div class="task-progress"><i style="width:${Math.min(100,p/w.goal*100)}%"></i></div><small>${p}/${w.goal} · ${rewardText(w.reward)}</small></div><button class="btn ${claimed?'ghost':done?'primary':'secondary'} compact" data-action="claimWeekly" data-id="${w.id}" ${claimed||!done?'disabled':''}>${claimed?'已领取':done?'领取':'进行中'}</button></div>`}).join('');const allReady=G.WEEKLY_TASKS.every(w=>state.weekly.claimed[w.id]);return `<div class="panel"><div class="section-title"><h3>本周星途</h3><span class="small muted">周起始 ${state.weekly.week}</span></div>${items}<div class="all-reward"><div><strong>周度全勤</strong><div class="small muted">${rewardText(G.WEEKLY_ALL_REWARD)}</div></div><button class="btn primary compact" data-action="claimWeeklyAll" ${!allReady||state.weekly.allClaimed?'disabled':''}>${state.weekly.allClaimed?'已领取':'领取'}</button></div></div>`}
function loginRewardPanel(){const info=G.loginRewardInfo(state);const next=info.nextIndex;return `<div class="panel v11-login-panel"><div class="section-title"><div><div class="kicker">SEVEN-DAY CONTRACT · CYCLE ${info.cycle}</div><h3>七曜登录契约</h3></div><span class="small muted">累计 ${info.totalClaims} 日</span></div><div class="v11-login-track">${G.LOGIN_REWARDS.map((r,i)=>{const claimed=!!info.claimed[i],current=!info.claimedToday&&i===next;return `<div class="v11-login-day ${claimed?'claimed':''} ${current?'current':''}"><b>DAY ${r.day}</b><span>${r.name}</span><small>${rewardText(r.reward)}</small><i>${claimed?'✓':current?'✦':'◇'}</i></div>`}).join('')}</div><div class="all-reward"><div><strong>${info.claimedToday?'今日星契已完成':`下一份：${G.LOGIN_REWARDS[next]?.name||G.LOGIN_REWARDS[0].name}`}</strong><div class="small muted">连续签到不要求每天不断档；完成第7日后，下个游戏日进入新一轮。</div></div><button class="btn primary" data-action="loginReward" ${info.claimedToday?'disabled':''}>${info.claimedToday?'今日已领取':'领取登录奖励'}</button></div></div>`}
function accountPanel(){const configured=CLOUD.configured(),meta=CLOUD.meta?.()||{},identityLabel=cloudMode?(meta.identityKind==='wechat'?'微信身份':'CloudBase 身份'):'本地游客';return `<div class="panel"><div class="section-title"><h3>玩家账号</h3><span class="badge">${identityLabel}</span></div><div class="account-row"><div><div class="small muted">云存档</div><strong>${cloudMode?'已连接，可跨设备绑定':'当前仅保存在本浏览器'}</strong></div><button class="btn secondary" data-action="cloud">${cloudMode?'刷新云存档':'连接云端'}</button></div>${configured?cloudMode?`<div class="link-box"><div class="small muted">设备 A：生成迁移码</div><button class="btn ghost" data-action="linkCreate">生成6位迁移码</button>${currentLink?`<div class="link-code">${currentLink.code}</div><div class="small muted">10分钟内在另一台设备输入</div>`:''}<div class="divider"></div><div class="small muted">设备 B：绑定到已有账号</div><div class="code-row"><input id="linkCodeInput" maxlength="6" placeholder="输入迁移码"/><button class="btn primary" data-action="linkRedeem">绑定</button></div></div>`:'<div class="small muted" style="margin-top:8px">连接云端后可生成跨设备迁移码。</div>':'<div class="small muted" style="margin-top:8px">当前 CloudBase 尚未配置；本地玩法完整可用。</div>'}</div>`}
function factionPanel(){const active=G.activeFactionBonuses(state);return `<div class="panel resonance"><div class="section-title"><h3>阵营共鸣</h3><span class="small muted">按上阵角色实时生效</span></div>${active.length?active.map(x=>`<div class="resonance-row"><span class="faction-dot ${x.faction}"></span><strong>${x.faction} ×${x.count}</strong><span>${x.two}${x.three?` · ${x.three}`:''}</span></div>`).join(''):'<div class="empty slim">同阵营上阵 2 人即可激活第一层共鸣。</div>'}</div>`}
function eventBanner(){const hero=G.byId(G.LIMITED_POOL.featured),pity=state.limited?.pity||0;return `<section class="event-banner"><div class="event-art">${portrait(hero,'event')}</div><div class="event-copy"><div class="kicker">LIMITED CONTRACT · 月影流光</div><h3>${hero.name} 概率提升</h3><p>SSR 3% · 60抽保底 · 歪出后下次SSR必定为${hero.name}</p><div class="event-meta"><span>当前限定保底 ${pity}/60</span><span>${state.limited?.guaranteed?'下次SSR必定UP':'UP占SSR的50%'}</span></div><button class="btn primary compact" data-tab="gacha">前往契约</button></div></section>`}
function shopView(){G.ensureShop(state);return `<div class="panel shop-head"><div class="section-title"><h3>星髓补给站</h3><span class="small muted">每日重置兑换次数</span></div><div class="shop-grid">${G.SHOP_ITEMS.map(i=>{const bought=Number(state.shop.purchases[i.id])||0,left=Math.max(0,i.dailyLimit-bought);return `<div class="shop-card"><div class="shop-icon">${i.id==='ticket'?'◎':i.id==='coin'?'◈':'◆'}</div><strong>${i.name}</strong><span>${i.desc}</span><div class="loot-chip">${rewardText(i.reward)}</div><small>消耗 星髓 ${i.cost.starCrystal} · 剩余 ${left}/${i.dailyLimit}</small><button class="btn primary compact" data-action="shopBuy" data-id="${i.id}" ${!left||state.starCrystal<i.cost.starCrystal?'disabled':''}>兑换</button></div>`}).join('')}</div></div><div class="panel art-direction-card"><div><div class="kicker">ART DIRECTION</div><h3>角色视觉已经接入首批概念卡面</h3><p class="muted">当前15名角色卡面使用经过裁切的概念视觉稿，后续可逐张替换正式透明立绘，不改业务代码。</p></div><img src="assets/art-direction/v05_concept_sheet.png" alt="星烬契约角色视觉概念稿"/></div>`}
function mailPanel(){const unread=G.unreadMailCount(state);return `<div class="panel mail-panel"><div class="section-title"><h3>星轨邮件</h3><span class="small muted">未领取 ${unread}</span></div><div class="mail-list">${(state.mails||[]).map(m=>`<div class="mail-card ${m.claimed?'claimed':''}"><div><strong>${m.title}</strong><span>${m.body}</span><small>${rewardText(m.reward)}</small></div><button class="btn ${m.claimed?'ghost':'secondary'} compact" data-action="claimMail" data-id="${m.id}" ${m.claimed?'disabled':''}>${m.claimed?'已领取':'领取'}</button></div>`).join('')}</div>${unread?'<button class="btn primary compact" data-action="claimAllMail">全部领取</button>':''}</div>`}
function home(){const ch=currentChapter(),boss=currentBoss(),lead=G.byId(state.formation[0]||'h001'),leadP=state.heroes[lead.id]||state.heroes[Object.keys(state.heroes)[0]];return `<section class="v09-home-stage v19-home-stage v20-home-stage chapter-${ch.id}" style="--v19-bg:url('${window.StarEmberAssets?.bg('home-main')||'assets/release/home-main-v20.jpg'}')"><div class="v20-release-stamp">V2.0 · RELEASE CANDIDATE</div><div class="v09-home-stars"></div><div class="v11-orbit-field"><i></i><i></i><i></i></div><div class="v11-comet comet-a"></div><div class="v11-comet comet-b"></div><div class="v09-home-art"><img src="${window.StarEmberAssets?.heroPortrait(lead.id,true)||('assets/characters/'+(lead.id==='h001'?'h001_full.jpg':lead.id+'.jpg'))}" alt="${lead.name}" onerror="this.style.display='none'"/><div class="v09-home-art-fade"></div></div><div class="v09-home-copy"><div class="v09-logo-en">STAR EMBER CONTRACT</div><div class="v09-logo-cn">星烬契约</div><p>以星火之名，缔结不灭的契约。</p><div class="v09-lead-chip"><span class="rarity-${lead.rarity}">${lead.rarity}</span><strong>${lead.name}</strong><small>${lead.faction} · ${lead.role} · Lv.${leadP?.level||1}</small></div></div><div class="v09-stage-card"><div class="kicker">CHAPTER ${ch.id} · ${ch.name}</div><h2>${boss?boss.name:`裂境 ${state.stage}`}</h2><p>${boss?'章节 Boss 已苏醒，首通可获得稀有养成奖励。':ch.theme}</p><div class="stage-line"><span>主线 ${state.stage}/30</span><span>${boss?'⚠ BOSS':`距离 Boss ${Math.max(0,ch.range[1]-state.stage)} 关`}</span><span>战力 ${G.formationPower(state)}</span></div><div class="btnrow"><button class="btn primary v09-main-action" data-action="battle">${boss?'挑战章节 Boss':'主线探索'}</button><button class="btn glass" data-tab="gacha">前往契约</button></div></div></section><section class="v09-quick-grid"><button class="v09-quick-card" data-tab="event"><b>☾</b><span><strong>月蚀回廊</strong><small>限定活动 · ${Math.max(0,G.EVENT_DAILY_ATTEMPTS-(state.event?.runs||0))} 次</small></span></button><button class="v09-quick-card" data-tab="inventory"><b>✧</b><span><strong>契灵整备</strong><small>装备 · 遗物 · 锻造</small></span></button><button class="v09-quick-card" data-tab="heroes"><b>✦</b><span><strong>契灵养成</strong><small>${Object.keys(state.heroes).length}/15 已缔结</small></span></button><button class="v09-quick-card" data-tab="shop"><b>◇</b><span><strong>星髓补给</strong><small>${state.starCrystal} 星髓可用</small></span></button></section><div class="grid metrics v09-metrics"><div class="panel"><div class="muted small">阵容战力</div><div class="metric">${G.formationPower(state)}</div></div><div class="panel"><div class="muted small">契灵图鉴</div><div class="metric">${Object.keys(state.heroes).length}/15</div></div><div class="panel"><div class="muted small">Boss击破</div><div class="metric">${state.bossClears.length}/6</div></div><div class="panel"><div class="muted small">限定保底</div><div class="metric">${state.limited?.pity||0}/60</div></div></div>${loginRewardPanel()}${eventBanner()}${mailPanel()}${factionPanel()}${dailyPanel()}${weeklyPanel()}${achievementPanel()}${accountPanel()}`}
function heroDetailPanel(){if(!state.heroes[selectedHeroId])selectedHeroId=state.formation[0]||Object.keys(state.heroes)[0];const h=G.byId(selectedHeroId),p=state.heroes[selectedHeroId],stats=G.computedStats(h,p,state),bond=G.bondInfo(state,h.id),sig=G.signatureForHero(h.id);return `<section class="v09-hero-detail rarity-border-${h.rarity}"><div class="v09-detail-art">${portrait(h,'profile')}</div><div class="v09-detail-copy"><div class="kicker">${h.faction} · ${h.role} · ${classBadge(h)}</div><h2>${h.name} <span class="rarity-${h.rarity}">${h.rarity}</span></h2><div class="stars">${stars(p.star)}</div><p>${G.HERO_VISUALS[h.id]?.title||''}</p><div class="v09-stat-grid"><span><small>生命</small><b>${stats.hp}</b></span><span><small>攻击</small><b>${stats.atk}</b></span><span><small>防御</small><b>${stats.def}</b></span><span><small>速度</small><b>${stats.spd}</b></span></div><div class="v09-skill v19-skill-detail">${skillIcon(h.id)}<div><b>${h.skill}</b><span>${skillText[h.skillType]||''}</span></div></div><div class="small muted">Lv.${p.level} · 战力 ${G.heroPower(h,p,state)} · 好感 Lv.${bond.level} · 觉醒 ${p.awakening||0}/3${sig?` · 专武 ${p.signature===sig.id?'已装备':(state.inventory.signatureWeapons?.[sig.id]||0)>0?'可装备':'未获得'}`:''}</div><div class="btnrow"><button class="btn secondary compact" data-action="level" data-id="${h.id}" ${p.level>=50?'disabled':''}>升级</button><button class="btn ghost compact" data-action="openGear" data-id="${h.id}">整备</button><button class="btn ghost compact" data-action="giftBond" data-id="${h.id}" ${(state.inventory.bondGift||0)<1?'disabled':''}>赠礼</button><button class="btn ghost compact" data-action="archive" data-id="${h.id}">角色档案</button></div></div></section>`}
function heroRosterGrid(formationMode=false){return `<div class="v09-roster-grid">${ownedList().map(x=>{const p=state.heroes[x.id],on=state.formation.includes(x.id);return `<button class="v09-roster-card rarity-border-${x.rarity} ${x.id===selectedHeroId?'active':''} ${on?'in-formation':''}" data-action="${formationMode?'form':'selectHero'}" data-id="${x.id}">${portrait(x,'roster')}<div class="v09-roster-meta"><span class="rarity-${x.rarity}">${x.rarity}</span><strong>${x.name}</strong><small>Lv.${p.level} · ${x.faction} · ${G.combatClassInfo(G.combatClassForHero(x)).name}</small></div>${on?'<i>上阵</i>':''}</button>`}).join('')}</div>`}
function formationStage(){const front=state.formation.filter(id=>state.formationRows?.[id]==='front'),back=state.formation.filter(id=>state.formationRows?.[id]!=='front');const unit=(id)=>{const h=G.byId(id),p=state.heroes[id];return `<div class="v17-row-unit rarity-${h.rarity}">${portrait(h,'formation')}<strong>${h.name}</strong><small>Lv.${p.level} · ${state.formationRows?.[id]==='front'?'前排':'后排'}</small><button class="btn ghost compact" data-action="formationRow" data-id="${id}">换到${state.formationRows?.[id]==='front'?'后':'前'}排</button></div>`};return `<section class="v09-formation-stage v17-formation-stage"><div class="v09-field-orbit"></div><div class="section-title"><h3>星轨阵列 · 前后排</h3><span class="small muted">前排承受多数近战攻击；后排可被远程/特殊技能锁定</span></div><div class="v17-row-label">后排 BACK</div><div class="v17-row-line back">${back.length?back.map(unit).join(''):'<div class="empty slim">暂无后排角色</div>'}</div><div class="v17-row-label">前排 FRONT</div><div class="v17-row-line front">${front.length?front.map(unit).join(''):'<div class="empty slim">暂无前排角色</div>'}</div><div class="v09-resonance-line">${formationSummary()}</div></section>`}
function talentPanel(heroId){const owned=G.heroTalents(state,heroId),tree=G.talentTree(heroId);return `<div class="panel v18-talent"><div class="section-title"><div><div class="kicker">STAR TRACE</div><h3>角色天赋</h3></div><span class="loot-chip">星痕点 ${state.inventory.talentPoints||0}</span></div><div class="v18-talent-tree">${tree.map((n,i)=>{const ok=owned.includes(n.id),req=!n.requires||owned.includes(n.requires);return `<button class="v18-talent-node ${ok?'active':''}" data-action="talent" data-id="${heroId}" data-node="${n.id}" ${ok||!req||(state.inventory.talentPoints||0)<n.cost?'disabled':''}><b>${ok?'✦':'◇'} ${n.name}</b><small>${n.desc}</small><em>${ok?'已点亮':`消耗 ${n.cost} 星痕点`}</em></button>`}).join('')}</div></div>`}
function heroesView(formationMode=false){return formationMode?`${formationStage()}${classCounterPanel()}${presetPanel()}<div class="panel"><div class="section-title"><h3>阵容候选</h3><span class="small muted">阵营共鸣会影响实际战斗属性</span></div>${heroRosterGrid(true)}</div>${factionPanel()}`:`${heroDetailPanel()}${talentPanel(selectedHeroId)}<div class="panel v09-roster-panel"><div class="section-title"><h3>契灵图鉴</h3><span class="small muted">已拥有 ${ownedList().length}/15</span></div>${heroRosterGrid(false)}</div>`}
function classCounterPanel(){return `<div class="panel v18-counter-panel"><div class="section-title"><h3>职业克制</h3><span class="small muted">克制 +18% · 被克制 -12%</span></div><div class="v18-counter-chain"><span>⚔ 突击</span><b>→</b><span>✧ 术式</span><b>→</b><span>⌁ 控制</span><b>→</b><span>◇ 守御</span><b>→</b><span>⚔ 突击</span><em>✦ 支援中立</em></div></div>`}
function presetPanel(){return `<div class="panel v18-presets"><div class="section-title"><h3>阵容预设</h3><span class="small muted">最多保存 3 套阵容/站位/遗物</span></div><div class="v18-preset-grid">${['1','2','3'].map(slot=>{const p=state.formationPresets?.[slot];return `<div class="v18-preset"><b>${p?.name||`阵容 ${slot}`}</b><small>${p?.formation?.map(id=>G.byId(id)?.name).filter(Boolean).join(' · ')||'尚未保存'}</small><div class="btnrow"><button class="btn ghost compact" data-action="presetSave" data-slot="${slot}">保存</button><button class="btn secondary compact" data-action="presetLoad" data-slot="${slot}" ${!p?'disabled':''}>载入</button></div></div>`}).join('')}</div></div>`}
function gachaView(){const pct=Math.min(100,state.pity/50*100),lp=Math.min(100,(state.limited?.pity||0)/60*100),up=G.byId(G.LIMITED_POOL.featured);const results=lastGacha.length?`<div class="panel"><h3>${gachaPool==='limited'?'限定':'常驻'}契约结果</h3><div class="result-grid">${lastGacha.map(r=>`<div class="result rarity-border-${r.hero.rarity} ${r.featured?'featured-result':''}">${portrait(r.hero,'result')}<span class="rarity-${r.hero.rarity}">${r.hero.rarity}</span><strong>${r.hero.name}</strong><small>${r.featured?'UP · ':''}${r.duplicate?`重复 · +${r.fragmentsGained}碎片`:'新契灵'}</small></div>`).join('')}</div></div>`:'';return `<section class="limited-gacha"><div class="limited-art">${portrait(up,'limited')}</div><div class="limited-copy"><div class="kicker">LIMITED · 月影流光</div><h2>${up.name}</h2><p>SSR概率提升 · 60抽保底 · 首个非UP SSR后，下次SSR必定UP</p><div class="progress"><i style="width:${lp}%"></i></div><div class="small muted">限定保底 ${state.limited?.pity||0}/60 · ${state.limited?.guaranteed?'下次SSR必定UP':'UP 50%'}</div><div class="btnrow"><button class="btn secondary" data-action="limited1" ${state.tickets<1?'disabled':''}>限定1次</button><button class="btn primary" data-action="limited10" ${state.tickets<10?'disabled':''}>限定10次</button></div></div></section><div class="panel gacha-stage compact-gacha"><div class="v12-newbie-badge ${state.newbieGacha?.claimed?'used':''}">${state.newbieGacha?.claimed?'新手十连已完成':'NEW · 首次常驻十连必得 SSR'}</div><h3>常驻星契轮</h3><p class="muted">SSR 3% · SR 22% · R 75%</p><div class="progress"><i style="width:${pct}%"></i></div><div class="small muted">SSR保底 ${state.pity}/50</div><div class="btnrow center"><button class="btn ghost" data-action="gacha1" ${state.tickets<1?'disabled':''}>常驻1次</button><button class="btn secondary" data-action="gacha10" ${state.tickets<10?'disabled':''}>常驻10次</button></div></div>${results}`}
function usedCount(itemId,exceptHero){let n=0;for(const [hid,p] of Object.entries(state.heroes)){if(hid===exceptHero)continue;for(const id of Object.values(p.equipment||{}))if(id===itemId)n++;}return n}
function inventoryView(){if(!state.heroes[selectedHeroId])selectedHeroId=state.formation[0]||Object.keys(state.heroes)[0];const h=G.byId(selectedHeroId),p=state.heroes[selectedHeroId];const heroChoices=ownedList().map(x=>`<button class="hero-pick ${x.id===selectedHeroId?'active':''}" data-action="selectHero" data-id="${x.id}"><span class="rarity-${x.rarity}">${x.name}</span><small>Lv.${x.level}</small></button>`).join('');const slots=['weapon','armor','charm'].map(slot=>{const current=G.equipmentById(p.equipment?.[slot]);const owned=G.EQUIPMENT.filter(x=>x.slot===slot&&(state.inventory.equipment[x.id]||0)>0);return `<div class="loadout-slot"><div class="slot-head"><span>${slotName[slot]}</span>${current?`<button class="text-btn" data-action="unequip" data-slot="${slot}">卸下</button>`:''}</div><div class="equipped ${current?'filled':''}">${current?`<div><strong class="rarity-${current.rarity}">${current.name}</strong><small>${statText(current.stats)}</small></div>`:`<span>未装备</span>`}</div><div class="gear-options">${owned.map(item=>{const total=state.inventory.equipment[item.id]||0,free=total-usedCount(item.id,selectedHeroId),isOn=p.equipment?.[slot]===item.id;return `<div class="gear-line"><button class="gear-option ${isOn?'active':''}" data-action="equip" data-id="${item.id}" ${!isOn&&free<=0?'disabled':''}><span><b class="rarity-${item.rarity}">${item.name} +${state.inventory.enhance?.[item.id]||0}</b><small>${statText(G.equipmentStats({equipment:{[slot]:item.id}},state))}</small></span><em>${isOn?'已装备':`持有 ${total}`}</em></button><button class="btn ghost compact enhance-btn" data-action="enhanceGear" data-id="${item.id}" ${(state.inventory.enhance?.[item.id]||0)>=10?'disabled':''}>强化</button></div>`}).join('')||'<div class="empty slim">尚未获得该槽位装备</div>'}</div></div>`}).join('');const relics=G.RELICS.filter(r=>(state.inventory.relics[r.id]||0)>0);const currentRelic=G.relicById(state.activeRelic);return `<div class="panel"><div class="section-title"><h3>契灵整备</h3><span class="small muted">装备直接影响战斗属性</span></div><div class="hero-picker">${heroChoices}</div><div class="selected-hero">${portrait(h,'selected')}<div><strong>${h.name}</strong><div class="small muted">当前战力 ${G.heroPower(h,p,state)}</div></div></div><div class="loadout-grid">${slots}</div></div><div class="panel"><div class="section-title"><h3>队伍遗物</h3><span class="small muted">全队唯一生效</span></div><div class="relic-active">${currentRelic?`<strong class="rarity-${currentRelic.rarity}">${currentRelic.name}</strong><span>${currentRelic.desc}</span>`:'<strong>未装备遗物</strong>'}</div><div class="relic-list">${relics.map(r=>`<button class="relic-card ${state.activeRelic===r.id?'active':''}" data-action="relic" data-id="${r.id}"><span class="rarity-${r.rarity}">${r.rarity}</span><strong>${r.name}</strong><small>${r.desc}</small></button>`).join('')||'<div class="empty">击败第 10/20/30 关 Boss 可获得核心遗物。</div>'}</div>${currentRelic?'<button class="btn ghost compact" data-action="relicClear">卸下遗物</button>':''}</div>${forgePanel()}`}

function forgePanel(){const spare=G.EQUIPMENT.filter(i=>(state.inventory.equipment[i.id]||0)>0).map(i=>{const total=Number(state.inventory.equipment[i.id])||0,used=usedCount(i.id,null),free=Math.max(0,total-used);return `<div class="forge-row"><div><strong class="rarity-${i.rarity}">${i.name}</strong><small>${i.set?`${G.EQUIPMENT_SETS[i.set]?.name}套装 · `:''}持有 ${total} · 闲置 ${free}</small></div><button class="btn ghost compact" data-action="dismantle" data-id="${i.id}" ${free<1?'disabled':''}>分解 +${G.DISMANTLE_DUST[i.rarity]}</button></div>`}).join('');return `<div class="panel forge-panel"><div class="section-title"><h3>星烬锻造</h3><span class="small muted">锻造尘 ${state.inventory.forgeDust||0} · 星铁 ${state.inventory.starIron||0}</span></div><div class="set-guide">${Object.values(G.EQUIPMENT_SETS).map(z=>`<div><strong>${z.name}套装</strong><span>${z.two.label} · ${z.three.label}</span></div>`).join('')}</div><div class="forge-recipes">${G.FORGE_RECIPES.map(r=>{const i=G.equipmentById(r.itemId),c=r.cost,ok=state.coin>=c.coin&&(state.inventory.starIron||0)>=c.starIron&&(state.inventory.forgeDust||0)>=c.forgeDust;return `<div class="forge-recipe"><div><span class="rarity-${i.rarity}">${i.rarity}</span><strong>${i.name}</strong><small>${G.EQUIPMENT_SETS[i.set]?.name||''} · ${statText(i.stats)}</small><em>锻造尘 ${c.forgeDust} · 星铁 ${c.starIron} · 烬币 ${c.coin}</em></div><button class="btn ${ok?'primary':'ghost'} compact" data-action="forge" data-id="${r.id}" ${!ok?'disabled':''}>锻造</button></div>`}).join('')}</div><details class="dismantle-box"><summary>分解闲置装备</summary>${spare||'<div class="empty slim">暂无可分解装备</div>'}</details></div>`}
function bondStoryCard(x){const b=G.bondInfo(state,x.id);return `<div class="bond-card"><div class="bond-head">${portrait(x,'bond')}<div><strong>${x.name}</strong><span>好感 Lv.${b.level}</span><small>${b.points}${b.next?` / ${b.next}`:' · MAX'}</small></div></div><div class="bond-stories">${b.stories.map(st=>`<div class="story ${st.unlocked?'open':'locked'}"><span>${st.unlocked?'✦':'◇'}</span><div><strong>${st.title}</strong><small>好感 Lv.${st.level} ${st.unlocked?'已解锁':'解锁'}</small></div></div>`).join('')}</div><button class="btn secondary compact wide" data-action="giftBond" data-id="${x.id}" ${(state.inventory.bondGift||0)<1?'disabled':''}>赠送星语花 · 持有 ${state.inventory.bondGift||0}</button></div>`}
function eventBossPanel(){G.ensureEventBoss(state);const b=state.eventBoss,left=Math.max(0,G.EVENT_BOSS.dailyAttempts-b.runs),board=eventLeaderboard.length?eventLeaderboard:G.localEventLeaderboard(state);return `<div class="panel event-boss"><div class="event-boss-head"><div><div class="kicker">CO-OP BOSS PROTOTYPE</div><h3>${G.EVENT_BOSS.name}</h3><p>${G.EVENT_BOSS.subtitle}</p></div><div class="boss-damage"><small>个人最佳</small><strong>${Number(b.bestDamage||0).toLocaleString()}</strong><span>今日剩余 ${left}/${G.EVENT_BOSS.dailyAttempts}</span></div></div><button class="btn primary" data-action="eventBoss" ${!left?'disabled':''}>讨伐一次</button><button class="btn ghost compact" data-action="leaderboard">刷新伤害榜</button><div class="leaderboard">${board.slice(0,6).map(x=>`<div class="rank-row ${x.isSelf?'self':''}"><b>#${x.rank}</b><span>${x.name||'引星者'}</span><strong>${Number(x.damage||0).toLocaleString()}</strong></div>`).join('')}</div></div>`}
function nightEventPanel(){const ev=state.nightEvent||{},left=Math.max(0,6-(ev.runs||0));return `<section class="panel v18-night-event"><div class="v18-night-hero"><div class="kicker">SECOND LIMITED EVENT</div><h2>星港夜航</h2><p>护送星港列车穿越流光风暴。活动关卡独立挑战次数，获取「航星徽」。</p><div class="stage-line"><span>航星徽 ${ev.voyageBadge||0}</span><span>今日 ${left}/6</span><span>首通 ${ev.firstClears?.length||0}/5</span></div></div><div class="v18-night-stages">${G.NIGHT_EVENT_STAGES.map(st=>`<button class="v18-night-stage" data-action="nightRun" data-id="${st.id}" ${G.formationPower(state)<st.power||left<=0?'disabled':''}><b>${st.id} ${st.name}</b><small>推荐 ${st.power}</small><em>${rewardText(st.reward)}</em></button>`).join('')}</div><div class="section-title"><h3>夜航补给</h3><span class="small muted">航星徽兑换</span></div><div class="shop-grid">${G.NIGHT_EVENT_SHOP.map(i=>{const bought=ev.shop?.[i.id]||0;return `<div class="shop-card"><strong>${i.name}</strong><small>消耗 ${i.cost} · ${bought}/${i.limit}</small><div class="loot-chip">${rewardText(i.reward)}</div><button class="btn secondary compact" data-action="nightBuy" data-id="${i.id}" ${bought>=i.limit||(ev.voyageBadge||0)<i.cost?'disabled':''}>兑换</button></div>`}).join('')}</div></section>`}
function eventView(){const featured=G.byId('h008'),clears=state.event?.clears||[],seal=state.event?.moonSeal||0;return `<section class="event-page-banner"><div class="event-moon"></div><div class="event-page-art">${portrait(featured,'limited')}</div><div class="event-page-copy"><div class="kicker">LIMITED EVENT · ${G.EVENT_CONFIG.name}</div><h2>追踪无灯客留下的月蚀坐标</h2><p>${G.EVENT_CONFIG.subtitle}</p><div class="event-currency">月蚀印 <strong>${seal}</strong> · 活动进度 ${clears.length}/${G.EVENT_STAGES.length} · 今日次数 ${Math.max(0,G.EVENT_DAILY_ATTEMPTS-(state.event?.runs||0))}/${G.EVENT_DAILY_ATTEMPTS}</div></div></section>${eventBossPanel()}<div class="panel"><div class="section-title"><h3>活动关卡</h3><span class="small muted">阵容战力达到推荐值即可自动结算</span></div><div class="event-stage-grid">${G.EVENT_STAGES.map(st=>{const done=clears.includes(st.id),left=Math.max(0,G.EVENT_DAILY_ATTEMPTS-(state.event?.runs||0)),ok=G.formationPower(state)>=st.power&&left>0;return `<div class="event-stage ${done?'done':''}"><div class="stage-code">${st.id}</div><strong>${st.name}</strong><span>推荐战力 ${st.power}</span><small>奖励 ${rewardText(st.reward)}${!state.event.firstClears.includes(st.id)&&st.first?` · 首通 ${rewardText(st.first)}`:''}</small><button class="btn ${ok?'primary':'ghost'} compact" data-action="eventRun" data-id="${st.id}" ${!ok?'disabled':''}>${done?'再次挑战':'首次挑战'}</button></div>`}).join('')}</div></div><div class="panel"><div class="section-title"><h3>月蚀商店</h3><span class="small muted">月蚀印 ${seal}</span></div><div class="event-shop-grid">${G.EVENT_SHOP.map(i=>{const bought=Number(state.event?.shop?.[i.id])||0,left=Math.max(0,i.limit-bought);return `<div class="shop-card"><div class="shop-icon">☾</div><strong>${i.name}</strong><span>${i.desc}</span><div class="loot-chip">${i.reward.heroId?`${G.byId(i.reward.heroId).name}碎片 ${i.reward.fragments}`:rewardText(i.reward)}</div><small>月蚀印 ${i.cost} · 剩余 ${left}/${i.limit}</small><button class="btn primary compact" data-action="eventBuy" data-id="${i.id}" ${!left||seal<i.cost?'disabled':''}>兑换</button></div>`}).join('')}</div></div><div class="panel"><div class="section-title"><h3>契灵羁绊</h3><span class="small muted">星语花 ${state.inventory.bondGift||0} · 好感解锁个人剧情</span></div><div class="bond-grid">${ownedList().slice(0,8).map(bondStoryCard).join('')}</div></div>${nightEventPanel()}`}
function resourcePanel(){G.ensureResourceRuns(state);return `<div class="panel"><div class="section-title"><h3>资源裂境</h3><span class="small muted">每日独立挑战次数</span></div><div class="dungeon-grid">${G.RESOURCE_DUNGEONS.map(d=>{const used=Number(state.resourceRuns.used[d.id])||0,left=Math.max(0,d.attempts-used),ok=G.formationPower(state)>=d.power;return `<div class="dungeon-card"><div class="dungeon-icon">${d.icon}</div><div class="dungeon-main"><strong>${d.name}</strong><span>${d.desc}</span><small>推荐战力 ${d.power} · 今日剩余 ${left}/${d.attempts}</small><div class="loot-chip">${rewardText(d.reward)}</div></div><button class="btn ${ok&&left?'primary':'ghost'} compact" data-action="resourceDungeon" data-id="${d.id}" ${!ok||!left?'disabled':''}>挑战</button></div>`}).join('')}</div></div>`}
function battleArena(){
  if(!lastBattle)return'';
  const timeline=lastBattle.timeline||[],frame=timeline[Math.min(battleFrame,Math.max(0,timeline.length-1))]||null;
  const enemies=frame?.enemies||G.enemyTeam(lastBattle.stage).map(e=>({...e,maxHp:e.hp,shield:0}));
  const allies=frame?.allies||state.formation.map(id=>{const h=G.byId(id),z=G.computedStats(h,state.heroes[id],state);return{id,name:h.name,hp:z.hp,maxHp:z.hp,shield:0}});
  const lastSkill=frame?.text||battleLog[Math.min(battleFrame,Math.max(0,battleLog.length-1))]||'',effect=frame?.effect||{kind:'info',value:0},fx=frame?.actor?.id?G.SKILL_FX?.[frame.actor.id]:null;
  const isSkill=/施放|发动|终焉|群体|治疗|护盾/.test(lastSkill);
  const unit=(u,side)=>{const hp=Math.max(0,Math.min(100,(u.hp||0)/(u.maxHp||1)*100)),h=side==='ally'?G.byId(u.id):null,acting=frame?.actor?.id===u.id&&frame?.side===(side==='ally'?'a':'e'),hit=!acting&&lastSkill.includes(u.name),dead=(u.hp||0)<=0;return `<div class="v10-battle-unit ${side} ${u.isBoss?'boss-unit':''} ${acting?'v11-acting':''} ${hit?'v11-hit':''} ${dead?'v11-down':''}" data-unit="${u.id}">${h?portrait(h,'battle'):`<div class="enemy-core">${u.isBoss?'♛':'◆'}</div>`}<div class="v10-unit-meta"><strong>${u.name}</strong><div class="hpbar"><i style="width:${hp}%"></i></div><small>${Math.round(u.hp||0)} / ${Math.round(u.maxHp||0)}${u.shield?` · 护盾${Math.round(u.shield)}`:''}</small>${u.stun?'<em class="v11-status">眩晕</em>':''}</div></div>`};
  const value=Number(effect.value)||0,label=effect.kind==='heal'?`+${value}`:effect.kind==='shield'?`◇ ${value||''}`:value?`-${value}`:'';
  return `<div class="panel battle-visual v10-battle-stage v11-battle-stage v12-battle-stage ${lastBattle.win?'win':'loss'}"><div class="battle-visual-head"><span>${lastBattle.boss?'BOSS战':'裂境战斗'} · Stage ${lastBattle.stage}</span><strong>${lastBattle.win?'VICTORY':'BATTLE RECORD'}</strong></div><div class="v10-enemy-line">${enemies.slice(0,5).map(e=>unit(e,'enemy')).join('')}</div><div class="v10-combat-center ${isSkill?'v11-skill-active':''} ${fx?'fx-'+fx.shape:''}" style="--skill-accent:${fx?.accent||'#b58ae6'}"><div class="skill-banner">${lastSkill||'星烬回响仍在战场中消散'}</div>${isSkill?'<div class="v11-skill-slash"></div>':''}${fx&&isSkill?`<div class="v12-skill-signature"><i></i><b>${fx.shape}</b></div>`:''}${label?`<div class="v12-float-number ${effect.kind}">${label}${effect.kind==='critical'?'<small>CRITICAL</small>':''}</div>`:''}<div class="battle-starline">✦ ───────── ✦</div></div><div class="v10-ally-line">${allies.slice(0,5).map(e=>unit(e,'ally')).join('')}</div><div class="battle-controls"><button class="btn ghost compact" data-action="battleReplay">${battleTimer&&!battlePaused?'播放中':'播放战斗'}</button><button class="btn ghost compact" data-action="battlePause">${battlePaused?'继续':'暂停'}</button><button class="btn ghost compact" data-action="battle2x">AUTO ×2</button><button class="btn ghost compact" data-action="battleSpeed">×${ui.battleSpeed}</button><button class="btn primary compact" data-action="showResult">战斗结算</button><span class="small muted">${timeline.length?`演出 ${Math.min(battleFrame+1,timeline.length)}/${timeline.length}`:`战报 ${battleLog.length}`}</span></div></div>`
}
async function toggleFormationRow(id){if(!state.formation.includes(id))return;state.formationRows=state.formationRows||{};state.formationRows[id]=state.formationRows[id]==='front'?'back':'front';await action(async()=>{if(cloudMode){const d=await CLOUD.formation(state.formation,state.formationRows);state=G.migrate(d.state)}else{G.setFormation(state,state.formation,state.formationRows);persist()}})}
function liveBattlePanel(){if(!liveSession||liveSession.status==='complete')return'';const p=liveSession.pending;const bossUnit=liveSession.enemies.find(x=>x.isBoss),phase=liveSession.boss?.phase||bossUnit?.phase||1;const energy=u=>Math.max(0,Math.min(100,Math.round((Number(u.energy)||0)/Math.max(1,Number(u.skillCost)||100)*100)));const breakHtml=bossUnit?.breakMax?`<div class="v17-break-wrap ${bossUnit.breakWindow?'v18-break-window':''}">${bossUnit.breakWindow?'<div class="kicker">BREAK WINDOW · 受到伤害 +35%</div>':''}<div class="small muted">BREAK ${bossUnit.breakGauge}/${bossUnit.breakMax} · 已击破 ${bossUnit.breakCount||0}</div><div class="v17-breakbar"><i style="width:${Math.max(0,Math.min(100,bossUnit.breakGauge/bossUnit.breakMax*100))}%"></i></div></div>`:'';const unit=(u,side)=>`<button class="v15-targetable v14-live-unit ${side} ${u.hp<=0?'down':''} ${selectedBattleTargetId===u.id?'targeted':''}" ${p&&((p.targetMode==='enemy'&&side==='enemy')||(p.targetMode==='ally'&&side==='ally'))&&u.hp>0?`data-action="sessionTarget" data-id="${u.id}"`:''}><div><strong>${u.name}${u.isBoss?` · P${u.phase||1}`:''}</strong><small>${Math.max(0,u.hp)} / ${u.maxHp}${u.shield?` · 护盾 ${u.shield}`:''}${u.silence?' · '+statusIcon('silence','沉默'):''}${u.taunt?' · '+statusIcon('taunt','嘲讽'):''}${u.stun?' · '+statusIcon('stun','眩晕'):''}</small></div><div class="v14-hp"><i style="width:${Math.max(0,Math.min(100,u.hp/u.maxHp*100))}%"></i></div></button>`;const skills=liveSession.allies.map(u=>{const h=G.byId(u.id),ready=p?.heroId===u.id,eng=energy(u);return `<button class="v15-skill-slot ${ready?'ready':eng>0?'charging':''} ${u.hp<=0?'down':''}" ${ready?'data-action="sessionSkill"':''} data-id="${u.id}" style="--energy:${eng*3.6}deg"><span class="v15-energy-ring">${portrait(h,'battle')}</span><b>${h?.name||u.name}</b>${h?skillIcon(h.id,'v19-mini-skill'):''}<small>${h?.skill||''}${u.cooldownLeft?` · CD ${u.cooldownLeft}`:''}</small><em>${eng}%</em></button>`}).join('');const targets=p?.targets?.length?`<div class="v15-target-hint">${p.targetMode==='enemy'?'选择技能目标':'选择治疗目标'} · ${selectedBattleTargetId?(p.targets.find(x=>x.id===selectedBattleTargetId)?.name||'未选择'):'未选择'}</div>`:'';return `<div class="panel v14-live-session v15-live-session"><div class="section-title"><div><div class="kicker">LIVE BATTLE SESSION · ROUND ${liveSession.round}</div><h3>手动技能战斗</h3></div><div class="v15-session-meta">${liveSession.boss?`<span class="v15-phase">BOSS PHASE ${phase}/3 · ${liveSession.boss.namePhase||liveSession.boss.name||''}</span>`:''}<span class="v14-session-state">${liveSession.status==='waiting'?'等待指令':'推进中'}</span></div></div>${breakHtml}<div class="v14-live-field"><div>${liveSession.enemies.map(x=>unit(x,'enemy')).join('')}</div><div class="v14-live-star">✦</div><div>${liveSession.allies.map(x=>unit(x,'ally')).join('')}</div></div><div class="v15-skill-dock"><div class="kicker">SKILL DECK · 五人技能栏</div><div class="v15-skill-grid">${skills}</div></div>${p?`<div class="v14-command v15-command"><div class="v14-command-orb">✦</div><div><div class="kicker">SKILL READY · ${Math.round((p.energy||0)/Math.max(1,p.skillCost||100)*100)}% · COST ${p.skillCost||100}</div><h3>${p.heroName} · ${p.skill}</h3><p>${p.targetMode==='none'?'无需选择目标。':p.targetMode==='ally'?'请选择一名存活队友作为目标。':'请选择一名存活敌人作为目标。'} 技能按钮已点亮，也可以执行普通攻击保留充能。</p>${targets}</div><div class="btnrow"><button class="btn ghost" data-action="sessionBasic">普通攻击</button><button class="btn primary" data-action="sessionSkill" ${(p.targetMode!=='none'&&!selectedBattleTargetId)?'disabled':''}>释放 ${p.skill}</button></div></div>`:''}<div class="btnrow"><button class="btn ghost compact" data-action="sessionCancel">撤离战斗</button><span class="small muted">会话 ${liveSession.id.slice(-8)} · 技能能量与目标均由服务器校验</span></div></div>`}
function formationSummary(){return state.formation.map(id=>{const h=G.byId(id),p=state.heroes[id];return `<span class="formation-chip rarity-${h.rarity}">${h.name} Lv.${p.level}</span>`}).join('')}
function chapterRoad(){return `<div class="chapter-road">${G.CHAPTERS.map(c=>{const boss=G.bossByStage(c.range[1]),done=state.bossClears.includes(c.range[1]),active=state.stage>=c.range[0]&&state.stage<=c.range[1];return `<div class="chapter-node ${done?'done':active?'active':''}"><div class="node-index">${done?'✓':c.id}</div><div><strong>${c.name}</strong><small>${c.range[0]}-${c.range[1]} · Boss ${boss.name}</small></div></div>`}).join('')}</div>`}
function battleStrategyPanel(){const manual=ui.skillMode==='manual',strategy=G.AUTO_STRATEGIES?.[ui.autoStrategy]||G.AUTO_STRATEGIES?.balanced;return `<div class="panel v13-strategy v14-strategy v16-strategy"><div class="section-title"><div><div class="kicker">BATTLE CONTROL</div><h3>战斗控制模式</h3></div><button class="toggle ${manual?'on':''}" data-action="skillMode">${manual?'手动技能':'全自动'}</button></div><p class="small muted">${manual?'技能充能时暂停，由你选择目标与技能。':'服务器一次性完成结算；自动策略会影响技能释放与目标优先级。'}</p>${!manual?`<div class="v16-auto-strategies">${Object.entries(G.AUTO_STRATEGIES||{}).map(([id,x])=>`<button class="${ui.autoStrategy===id?'active':''}" data-action="autoStrategy" data-id="${id}"><b>${x.name}</b><small>${x.desc}</small></button>`).join('')}</div><div class="small muted">当前策略：${strategy?.name||'均衡'}</div>`:'<div class="v14-manual-note">✦ 支持断线恢复、目标选择、沉默/嘲讽等状态；每次指令由服务端校验。</div>'}</div>`}
function replayPanel(){const rows=G.battleReplays?.(state)||[];return `<div class="panel v16-replays"><div class="section-title"><div><div class="kicker">BATTLE ARCHIVE</div><h3>最近战斗录像</h3></div><span class="small muted">最多保存 5 场 · 回放不重复结算</span></div>${rows.length?rows.map(r=>`<button class="v16-replay-row" data-action="replayOpen" data-id="${r.id}"><span>${r.win?'✦':'◇'} Stage ${r.stage}${r.boss?` · ${r.boss.name}`:''}</span><small>${r.skillMode==='manual'?'手动':'AUTO '+(G.autoStrategyInfo?.(r.autoStrategy)?.name||'均衡')} · ${new Date(r.createdAt).toLocaleString()}</small></button>`).join(''):'<div class="empty">完成一场战斗后会生成录像。</div>'}</div>`}
function battleStatsPanel(){const rows=lastBattle?.stats||liveSession?.stats||[];const combos=lastBattle?.combosUsed||liveSession?.combosUsed||[];return `<div class="panel v17-stats"><div class="section-title"><div><div class="kicker">BATTLE REPORT</div><h3>战斗统计</h3></div><span class="small muted">伤害 · 治疗 · 护盾</span></div>${rows.length?`<div class="v17-stat-grid">${rows.slice(0,6).map((x,i)=>`<div class="v17-stat-row"><b>#${i+1} ${x.name}</b><span>伤害 ${x.damage||0}</span><span>治疗 ${x.heal||0}</span><span>护盾 ${x.shield||0}</span></div>`).join('')}</div>`:'<div class="empty slim">完成战斗后显示本场贡献统计。</div>'}${combos.length?`<div class="v17-combos">连携技：${combos.map(id=>G.COMBO_SKILLS?.find(c=>c.id===id)?.name||id).join(' · ')}</div>`:''}</div>`}
function sweepPanel(){const info=G.sweepInfo(state),stage=Math.max(1,state.stage-1),can=state.campaignCompleted||state.stage>1;return `<div class="panel v18-sweep"><div class="section-title"><div><div class="kicker">EXPEDITION</div><h3>裂境扫荡</h3></div><span class="loot-chip">今日 ${info.left}/${info.limit}</span></div><p class="small muted">对已通关 Stage ${stage} 快速结算，不推进主线；可获得烬币、星铁，并小概率获得星痕点。</p><div class="btnrow"><button class="btn secondary" data-action="sweep" data-count="1" ${!can||info.left<1?'disabled':''}>扫荡 ×1</button><button class="btn primary" data-action="sweep" data-count="5" ${!can||info.left<5?'disabled':''}>扫荡 ×5</button></div></div>`}
function explore(){const boss=currentBoss(),ch=currentChapter();return `<section class="hero-banner explore-banner chapter-${ch.id}"><div class="kicker">裂境探索 · ${ch.name}</div><h2>${boss?`Boss · ${boss.name}`:`裂境 ${state.stage}`}</h2><p>${boss?`首通奖励：${boss.firstReward.equipment?G.equipmentById(boss.firstReward.equipment).name:G.relicById(boss.firstReward.relic).name}`:`推进至第 ${ch.range[1]} 关挑战章节 Boss`}</p><div class="formation-strip">${formationSummary()}</div><button class="btn primary wide" data-action="battle">${boss?'进入 Boss 战':ui.skillMode==='manual'?'开始手动技能战斗':'开始自动战斗'}</button></section>${battleStrategyPanel()}<div class="panel"><div class="section-title"><h3>六章裂境</h3><span class="small muted">Boss首通掉落固定奖励</span></div>${chapterRoad()}</div>${sweepPanel()}${resourcePanel()}${factionPanel()}${liveBattlePanel()}${battleArena()}${replayPanel()}${battleStatsPanel()}${battleLog.length?`<div class="panel"><h3>战斗记录</h3><div class="battle-log">${battleLog.map((x,i)=>`<div class="${x.startsWith('⚠')?'boss-log':x.startsWith('✦')?'loot-log':i===battleLog.length-1?(x.startsWith('胜利')?'battle-win':x.startsWith('挑战失败')?'battle-loss':''):''}">${x}</div>`).join('')}</div></div>`:''}<div class="panel"><h3>开发者选项</h3><button class="btn ghost" data-action="reset" ${cloudMode?'disabled':''}>重置本地存档</button><div class="small muted" style="margin-top:8px">云端存档不会从客户端直接删除。</div></div>`}
function bootOverlay(){return booting?`<div class="v10-boot"><div class="v10-boot-stars"></div><div class="v10-boot-mark">✦</div><div class="v10-boot-title">星烬契约</div><div class="v10-boot-en">STAR EMBER CONTRACT</div><div class="v10-boot-line"></div><small>v1.7 · 正在校准星轨阵列…</small></div>`:''}
function tutorialOverlay(){if(ui.tutorialDone||booting)return'';const steps=[{title:'欢迎，引星者',text:'裂潮撕开了旧世界。你将与契灵缔约，寻找仍未熄灭的星烬。',tab:'home',cta:'进入星契轮'},{title:'缔结契约',text:'消耗契灵印可以召唤契灵。十连更适合快速建立第一支队伍。',tab:'gacha',cta:'查看契约'},{title:'认识契灵',text:'每名契灵拥有阵营、职业和独立技能。升级、升星、觉醒会提升实战能力。',tab:'heroes',cta:'查看契灵'},{title:'编成星轨',text:'最多五人出战。阵营共鸣、治疗、控制与爆发的组合会显著影响战斗。',tab:'formation',cta:'配置阵容'},{title:'踏入裂境',text:'挑战主线获取烬币、契灵印与装备。Boss 首通还能得到固定稀有奖励。',tab:'explore',cta:'开始探索'}],x=steps[Math.min(ui.tutorialStep,steps.length-1)];return `<div class="v10-modal-layer tutorial-layer"><div class="v10-tutorial"><div class="kicker">NEW VOYAGE · ${ui.tutorialStep+1}/${steps.length}</div><h2>${x.title}</h2><p>${x.text}</p><div class="v10-tutorial-orbit">✦</div><div class="btnrow"><button class="btn ghost" data-action="tutorialSkip">跳过</button><button class="btn primary" data-action="tutorialNext">${x.cta}</button></div></div></div>`}
function gachaRevealOverlay(){if(!revealOpen||!lastGacha.length)return'';const r=lastGacha[Math.min(revealIndex,lastGacha.length-1)],h=r.hero,v=G.HERO_VISUALS[h.id]||{};return `<div class="v10-modal-layer reveal-layer rarity-bg-${h.rarity}"><img class="v11-reveal-bg" src="${window.StarEmberAssets?.heroPortrait(h.id,true)||('assets/characters/'+(h.id==='h001'?'h001_full.jpg':h.id+'.jpg'))}" alt=""/><div class="v10-reveal-wheel v19-reveal-wheel" style="background-image:url('${window.StarEmberAssets?.bg('gacha-orbit')||'assets/ui/backgrounds/gacha-orbit.svg'}')"><div class="wheel-a"></div><div class="wheel-b"></div><span>✦</span></div><div class="v10-reveal-card rarity-border-${h.rarity}">${portrait(h,'reveal')}<div class="v10-reveal-copy"><div class="kicker">${r.featured?'FEATURED · ':''}${h.rarity} CONTRACT</div><h2>${h.name}</h2><p>${v.title||h.faction+' · '+h.role}</p><div class="stars">${stars(state.heroes[h.id]?.star||1)}</div><small>${r.duplicate?`重复契约 · 转化 ${r.fragmentsGained} 碎片`:'NEW · 首次缔约'}</small></div></div><div class="v10-reveal-actions"><button class="btn ghost" data-action="revealClose">跳过演出</button><button class="btn primary" data-action="revealNext">${revealIndex<lastGacha.length-1?`下一个 ${revealIndex+1}/${lastGacha.length}`:'查看结果'}</button></div></div>`}
function bossIntroOverlay(){const boss=currentBoss();if(!bossIntroOpen||!boss)return'';const chapter=currentChapter();return `<div class="v10-modal-layer v11-boss-layer"><div class="v11-boss-intro"><div class="v20-boss-visual"><img src="${window.StarEmberAssets?.bossSplash?.(boss.stage)||window.StarEmberAssets?.boss(boss.stage)||`assets/ui/bosses/stage-${boss.stage}.svg`}" alt="${boss.name}"/></div><div class="kicker">CHAPTER ${chapter.id} · BOSS AWAKENING</div><h2>${boss.name}</h2><p>${boss.skill}</p><div class="v11-boss-threat"><span>推荐阵容战力</span><strong>${Math.round(3500+boss.stage*520).toLocaleString()}</strong><small>当前 ${G.formationPower(state).toLocaleString()}</small></div><div class="btnrow"><button class="btn ghost" data-action="bossCancel">暂不挑战</button><button class="btn danger" data-action="bossChallenge">进入 Boss 战</button></div></div></div>`}
function currentStory(){return G.storyForStage?.(state.stage)||null}
function storyOverlay(){const st=currentStory();if(!storyOpen||!st)return'';const line=st.lines[Math.min(storyIndex,st.lines.length-1)],hero=line.heroId?G.byId(line.heroId):null;return `<div class="v10-modal-layer v12-story-layer"><div class="v12-story-scene">${hero?`<div class="v12-story-art">${portrait(hero,'story')}</div>`:'<div class="v12-story-star">✦</div>'}<div class="v12-story-chapter"><div class="kicker">CHAPTER ${st.chapter} · STORY</div><h2>${st.title}</h2></div><div class="v12-dialogue"><strong>${line.speaker}</strong><p>${line.text}</p><div class="btnrow"><button class="btn ghost" data-action="storySkip">跳过剧情</button><button class="btn primary" data-action="storyNext">${storyIndex<st.lines.length-1?'继续':'进入战斗'}</button></div></div></div></div>`}
function battleResultOverlay(){if(!resultOpen||!lastBattle)return'';const r=lastBattle,voiceHero=state.formation[0];return `<div class="v10-modal-layer v12-result-layer"><div class="v12-result-card ${r.win?'victory':'defeat'}"><div class="v12-result-emblem">${r.win?'✦':'◇'}</div><div class="kicker">${r.win?'BATTLE COMPLETE':'RESONANCE LOST'}</div><h2>${r.win?'胜 利':'挑战失败'}</h2><p>Stage ${r.stage} · 阵容战力 ${Number(r.formationPower||0).toLocaleString()}</p>${r.win?`<div class="v12-result-loot"><div><small>烬币</small><strong>+${r.rewards?.coin||0}</strong></div><div><small>契灵印</small><strong>+${r.rewards?.tickets||0}</strong></div>${(r.drops||[]).map(x=>`<div><small>${x.kind==='relic'?'遗物':'装备'}</small><strong class="rarity-${x.item.rarity}">${x.item.name}</strong></div>`).join('')}</div>`:'<div class="v12-result-tip">升级、装备与阵营共鸣都能提高下一次挑战成功率。</div>'}<div class="btnrow"><button class="btn ghost" data-action="resultClose">返回战场</button>${r.win&&voiceHero?`<button class="btn secondary" data-action="voice" data-id="${voiceHero}" data-voice="victory">胜利语音</button>`:''}<button class="btn primary" data-action="resultContinue">${r.win?'继续探索':'整备后重试'}</button></div></div></div>`}

function archiveOverlay(){if(!archiveOpen)return'';const id=archiveHeroId||selectedHeroId,h=G.byId(id),a=G.archiveForHero?.(id);if(!h||!a)return'';return `<div class="v10-modal-layer v13-archive-layer"><div class="v13-archive"><button class="v10-close" data-action="archiveClose">×</button><div class="v13-archive-art">${portrait(h,'archive')}</div><div class="v13-archive-copy"><div class="kicker">CONTRACT ARCHIVE · ${h.rarity}</div><h2>${h.name} <small>「${a.codename}」</small></h2><div class="v13-archive-tags"><span>${h.faction}</span><span>${h.role}</span><span>${a.affiliation}</span></div><p>${a.profile}</p><dl><dt>出身</dt><dd>${a.origin}</dd><dt>记忆片段</dt><dd>${a.memory}</dd><dt>偏好</dt><dd>${a.likes}</dd><dt>不擅长</dt><dd>${a.dislikes}</dd><dt>人物关系</dt><dd>${a.relation}</dd></dl><div class="btnrow"><button class="btn secondary" data-action="voice" data-id="${id}" data-voice="acquire">契约语音</button><button class="btn ghost" data-action="archiveClose">关闭档案</button></div></div></div></div>`}
function firstContractOverlay(){if(booting||ui.tutorialDone===false||ui.firstContractDone||state.newbieGacha?.claimed||tab!=='gacha')return'';return `<div class="v10-modal-layer v13-first-contract"><div class="v13-first-card"><div class="v13-first-orbit">✦</div><div class="kicker">FIRST CONTRACT</div><h2>完成你的第一次十连契约</h2><p>首次常驻十连必定获得至少 1 名 SSR。完成后，新手首契引导永久结束。</p><div class="loot-chip">当前契灵印 ${state.tickets} / 10</div><div class="btnrow"><button class="btn ghost" data-action="firstContractLater">稍后</button><button class="btn primary" data-action="firstContractStart" ${state.tickets<10?'disabled':''}>开始首契十连</button></div></div></div>`}
function settingsOverlay(){if(!settingsOpen)return'';return `<div class="v10-modal-layer"><div class="v10-settings"><div class="section-title"><div><div class="kicker">SYSTEM</div><h2>设置</h2></div><button class="v10-close" data-action="settingsClose">×</button></div><div class="setting-row"><span>音效</span><button class="toggle ${ui.sound?'on':''}" data-action="toggleSound">${ui.sound?'开启':'关闭'}</button></div><div class="setting-row"><span>背景音乐框架</span><button class="toggle ${ui.music?'on':''}" data-action="toggleMusic">${ui.music?'开启':'关闭'}</button></div><div class="setting-row"><span>角色语音预览</span><button class="toggle ${ui.voice?'on':''}" data-action="toggleVoice">${ui.voice?'开启':'关闭'}</button></div><div class="setting-row"><span>战斗演出速度</span><button class="toggle on" data-action="battleSpeed">×${ui.battleSpeed}</button></div><div class="setting-row"><span>视觉特效质量</span><button class="toggle on" data-action="fxQuality">${ui.fxQuality==='high'?'高':ui.fxQuality==='medium'?'中':'省电'}</button></div><div class="panel subtle"><b>v2.0 Release Candidate</b><p class="small muted">正式试玩资源包：15名角色全屏资源、Boss Splash、首页主视觉、发布清单与 CloudBase/微信小游戏部署检查。</p></div></div></div>`}
function nav(){const items=[['home','首页','⌂'],['heroes','契灵','✦'],['gacha','契约','◎'],['formation','阵容','◇'],['inventory','整备','▣'],['shop','商店','¤'],['event','活动','☾'],['explore','探索','▲']];return `<nav class="nav v09-nav">${items.map(([k,n,icon])=>`<button class="${tab===k?'active':''}" data-tab="${k}"><span class="nav-icon">${icon}</span><em>${n}</em></button>`).join('')}</nav>`}
function render(){const body=tab==='home'?home():tab==='heroes'?heroesView(false):tab==='gacha'?gachaView():tab==='formation'?heroesView(true):tab==='inventory'?inventoryView():tab==='shop'?shopView():tab==='event'?eventView():explore();document.getElementById('app').innerHTML=`<main class="app v10-app v11-app v19-app v20-app fx-${ui.fxQuality} ${busy?'busy':''}">${renderTop()}${body}</main>${nav()}${bootOverlay()}${tutorialOverlay()}${gachaRevealOverlay()}${storyOverlay()}${bossIntroOverlay()}${battleResultOverlay()}${archiveOverlay()}${firstContractOverlay()}${settingsOverlay()}${busy?'<div class="loading">同步中…</div>':''}`;bind()}
function bind(){
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(busy)return;tab=b.dataset.tab;render()});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action,id=b.dataset.id,slot=b.dataset.slot,sig=b.dataset.sig;sfx('tap');
    if(a==='gacha1'){gachaPool='standard';gacha(1)}else if(a==='gacha10'){gachaPool='standard';gacha(10)}else if(a==='limited1')limitedGacha(1);else if(a==='limited10')limitedGacha(10);else if(a==='level')upgrade(id,'level');else if(a==='star')upgrade(id,'star');else if(a==='form')toggleFormation(id);else if(a==='formationRow')toggleFormationRow(id);else if(a==='talent')talentUnlock(id,b.dataset.node);else if(a==='presetSave')presetAction('save',slot);else if(a==='presetLoad')presetAction('load',slot);else if(a==='sweep')sweepRun(Number(b.dataset.count)||1);else if(a==='nightRun')nightRun(id);else if(a==='nightBuy')nightBuy(id);else if(a==='battle'){const st=currentStory();if(st&&!state.storySeen?.includes(st.id)){storyOpen=true;storyIndex=0;render()}else if(currentBoss()){bossIntroOpen=true;render()}else battle();}else if(a==='bossChallenge'){bossIntroOpen=false,storyOpen=false,storyIndex=0,resultOpen=false;battle()}else if(a==='bossCancel'){bossIntroOpen=false,storyOpen=false,storyIndex=0,resultOpen=false;render()}else if(a==='loginReward')claimLoginReward();else if(a==='claimDaily')claimDaily(id,false);else if(a==='claimAll')claimDaily('',true);else if(a==='claimWeekly')claimWeekly(id,false);else if(a==='claimWeeklyAll')claimWeekly('',true);else if(a==='shopBuy')shopBuy(id);else if(a==='cloud')(cloudMode?syncCloud():connectCloud());else if(a==='linkCreate')createLinkCode();else if(a==='linkRedeem')redeemLinkCode();else if(a==='openGear'){selectedHeroId=id;tab='inventory';render()}else if(a==='selectHero'){selectedHeroId=id;render()}else if(a==='equip')setLoadout('gear',{heroId:selectedHeroId,itemId:id});else if(a==='unequip')setLoadout('unequip',{heroId:selectedHeroId,slot});else if(a==='relic')setLoadout('relic',{itemId:id});else if(a==='relicClear')setLoadout('relic',{itemId:null});else if(a==='enhanceGear')enhanceGear(id);else if(a==='resourceDungeon')resourceDungeon(id);else if(a==='claimAchievement')claimAchievement(id);else if(a==='dismantle')dismantleGear(id);else if(a==='forge')forgeGear(id);else if(a==='eventRun')runEvent(id);else if(a==='eventBuy')eventBuy(id);else if(a==='giftBond')giftBond(id);else if(a==='equipSig')setSignature(id,sig);else if(a==='awaken')awaken(id);else if(a==='claimMail')mailClaim(id,false);else if(a==='claimAllMail')mailClaim('',true);else if(a==='eventBoss')runEventBoss();else if(a==='leaderboard')refreshLeaderboard();else if(a==='battleReplay'){clearInterval(battleTimer);battlePaused=false;battleFrame=0;render();const frames=lastBattle?.timeline?.length||battleLog.length;battleTimer=setInterval(()=>{battleFrame++;const text=lastBattle?.timeline?.[battleFrame]?.text||'';if(text.includes('施放')||text.includes('发动'))sfx('skill');if(battleFrame>=frames-1){clearInterval(battleTimer);battleTimer=null;resultOpen=true}render()},Math.round(520/ui.battleSpeed))}else if(a==='battlePause'){if(battleTimer){clearInterval(battleTimer);battleTimer=null;battlePaused=true}else if(lastBattle?.timeline?.length&&battleFrame<lastBattle.timeline.length-1){battlePaused=false;const frames=lastBattle.timeline.length;battleTimer=setInterval(()=>{battleFrame++;if(battleFrame>=frames-1){clearInterval(battleTimer);battleTimer=null;resultOpen=true}render()},Math.round(520/ui.battleSpeed))}render()}else if(a==='battle2x'){ui.battleSpeed=2;saveUi();battlePaused=false;render()}else if(a==='battleSpeed'){ui.battleSpeed=ui.battleSpeed===1?1.5:ui.battleSpeed===1.5?2:1;saveUi();render()}else if(a==='fxQuality'){ui.fxQuality=ui.fxQuality==='high'?'medium':ui.fxQuality==='medium'?'low':'high';saveUi();render()}else if(a==='settings'){settingsOpen=true;render()}else if(a==='settingsClose'){settingsOpen=false;render()}else if(a==='toggleSound'){ui.sound=!ui.sound;saveUi();render()}else if(a==='toggleMusic'){ui.music=!ui.music;saveUi();render()}else if(a==='toggleVoice'){ui.voice=!ui.voice;saveUi();render()}else if(a==='voice'){playVoice(id,b.dataset.voice||'acquire')}else if(a==='storySkip'){storyOpen=false;storyIndex=0;if(currentBoss()){bossIntroOpen=true;render()}else battle()}else if(a==='storyNext'){const st=currentStory();if(st&&storyIndex<st.lines.length-1){storyIndex++;render()}else{storyOpen=false;storyIndex=0;if(currentBoss()){bossIntroOpen=true;render()}else battle()}}else if(a==='showResult'){resultOpen=true;render()}else if(a==='resultClose'){resultOpen=false;render()}else if(a==='resultContinue'){resultOpen=false;tab=lastBattle?.win?'explore':'inventory';render()}else if(a==='tutorialSkip'){ui.tutorialDone=true;saveUi();render()}else if(a==='tutorialNext'){const steps=['gacha','heroes','formation','explore'];if(ui.tutorialStep>=4){ui.tutorialDone=true;saveUi();tab='explore'}else{tab=steps[ui.tutorialStep]||'home';ui.tutorialStep++;saveUi()}render()}else if(a==='revealNext'){if(revealIndex<lastGacha.length-1){revealIndex++;const h=lastGacha[revealIndex]?.hero;if(h?.rarity==='SSR')sfx('rare');if(h)playVoice(h.id,'acquire');render()}else{revealOpen=false;render()}}else if(a==='revealClose'){revealOpen=false;render()}else if(a==='archive'){archiveHeroId=id;archiveOpen=true;render()}else if(a==='archiveClose'){archiveOpen=false;archiveHeroId=null;render()}else if(a==='autoStrategy'){if(G.AUTO_STRATEGIES?.[id]){ui.autoStrategy=id;saveUi();toast(`AUTO策略：${G.AUTO_STRATEGIES[id].name}`);render()}}else if(a==='replayOpen'){const r=(G.battleReplays?.(state)||[]).find(x=>x.id===id);if(r){lastBattle={...r,replay:true};battleLog=[...(r.log||[])];battleFrame=0;resultOpen=false;toast(`载入 Stage ${r.stage} 战斗录像`);render()}}else if(a==='skillMode'){if(liveSession&&['running','waiting'].includes(liveSession.status)){toast('请先完成或撤离当前手动战斗');return}ui.skillMode=ui.skillMode==='auto'?'manual':'auto';saveUi();render()}else if(a==='sessionTarget'){selectedBattleTargetId=id;render()}else if(a==='sessionSkill'){commandLiveBattle('skill')}else if(a==='sessionBasic'){commandLiveBattle('basic')}else if(a==='sessionCancel'){cancelLiveBattle()}else if(a==='firstContractStart'){ui.firstContractDone=true;saveUi();gachaPool='standard';gacha(10)}else if(a==='firstContractLater'){ui.firstContractDone=true;saveUi();render()}else if(a==='reset'&&!cloudMode&&confirm('确定重置本地试玩进度吗？')){saves.reset();state=G.newPlayer('guest-'+Math.random().toString(36).slice(2,10));selectedHeroId='h004';lastGacha=[];battleLog=[];battleFrame=0;persist();tab='home';render()}
  })
}
